# First, let me extract the individual questions from the context
questions = []
for line in context.split('\n'):
    if '|| Instance:' in line:
        # Extract the question text after "Instance:"
        parts = line.split('|| Instance:')
        if len(parts) > 1:
            questions.append(parts[1].strip())

print(f"Found {len(questions)} questions:")
for i, q in enumerate(questions, 1):
    print(f"{i}. {q[:80]}...")
